export const init=()=>{document.addEventListener("click",e=>{const t=e.target.closest(".erp-user-chip"),r=document.querySelector(".erp-user-menu"),o=r?.querySelector(".erp-dropdown");if(r&&o){if(t&&r.contains(t)){e.preventDefault(),e.stopPropagation();const r=o.classList.contains("show");return o.classList.toggle("show",!r),void t.setAttribute("aria-expanded",String(!r))}r.contains(e.target)||(o.classList.remove("show"),r.querySelector(".erp-user-chip")?.setAttribute("aria-expanded","false"))}}),document.addEventListener("keydown",e=>{if("Escape"!==e.key)return;const t=document.querySelector(".erp-dropdown"),r=document.querySelector(".erp-user-chip");t?.classList.remove("show"),r?.setAttribute("aria-expanded","false"),r?.focus()});const e=document.documentElement,t=document.getElementById("erp-theme-toggle");if(t){const r=()=>{try{return localStorage.getItem("erp-moodle-theme")||"light"}catch(e){return"light"}},o=r=>{e.setAttribute("data-bs-theme",r);try{localStorage.setItem("erp-moodle-theme",r)}catch(e){}t.setAttribute("aria-pressed",String("dark"===r)),t.setAttribute("title","dark"===r?"Switch to light theme":"Switch to dark theme")};o(r()),t.addEventListener("click",()=>{o("dark"===r()?"light":"dark")})}};